// AsBoardCreatedEvent returns the union data inside the Event as a BoardCreatedEvent
func (t Event) AsBoardCreatedEvent() (BoardCreatedEvent, error) {
	var body BoardCreatedEvent
	err := json.Unmarshal(t.union, &body)
	return body, err
}

